import pandas as pd

def rows_to_df(rows,dims):
  out=[]
  for r in rows or []:
    keys=r.get('keys') or []
    rec={dims[i]:(keys[i] if i<len(keys) else None) for i in range(len(dims))}
    rec.update({k:r.get(k) for k in ['clicks','impressions','ctr','position']})
    out.append(rec)
  return pd.DataFrame(out)
